#: A notice's `data`, as compact UTF-8 JSON. Details stay on the existing read routes.
MAX_DATA_BYTES = 4 * 1024


def measure_data_bytes(value: dict[str, Any]) -> int:
    """The size the 4 KiB cap counts: compact JSON, UTF-8."""
    return len(json.dumps(value, separators=(",", ":"), ensure_ascii=False, default=str).encode("utf-8"))


def check_data(value: dict[str, Any]) -> dict[str, Any]:
    if measure_data_bytes(value) > MAX_DATA_BYTES:
        raise ValueError("data is over 4 KiB: send a notice, and let the client read details from its route")
    return value


Data = Annotated[dict[str, Any], AfterValidator(check_data)]


class LiveRefs(BaseModel):
    """What the event is about, outermost first. The server fills every ancestor it knows at emit time."""

    model_config = ConfigDict(frozen=True)

    #: The top project it is filed under (an experiment's parent; never the experiment itself).
    project: UUID | None = None
    experiment: UUID | None = None
    run: UUID | None = None
    sample: UUID | None = None

    def get_anchor(self) -> UUID | None:
        """Where access is decided: the experiment, else the project. None = a team event (no project)."""
        return self.experiment or self.project

    def is_empty(self) -> bool:
        return not (self.project or self.experiment or self.run or self.sample)


class LiveEvent(BaseModel):
    """One published notice. `seq` is its place in the one global order; a client's cursor is the last one it saw."""

    model_config = ConfigDict(frozen=True)

    #: Stamped at publication, strictly increasing, gaps normal (other teams', filtered). 0 = nothing published yet
    #: (only a control event at an empty head carries it).
    seq: int = Field(ge=0)
    #: When the change happened, on the writer's clock (not when it was published).
    at: AwareDatetime
    #: A `LiveEventKind` value or `entity.<audit type>`. Any well-formed kind is accepted: newer servers add kinds.
    kind: str = Field(pattern=KIND_PATTERN, max_length=MAX_KIND_CHARS)
    refs: LiveRefs = Field(default_factory=LiveRefs)
    data: Data = Field(default_factory=dict)

    def get_family(self) -> LiveFamily | None:
        return get_family(self.kind)

    def is_control(self) -> bool:
        """`resync` or `lagged`: about the stream, not the data."""
        return self.kind in CONTROL_KINDS
